#!/usr/bin/env python3
"""Conan recipe — libucimf 2.3.8 (Unicode Console Input Method Framework, Autotools).

libucimf is the core library of UCIMF, a Unicode console (framebuffer)
CJK input method framework (Debian: libucimf, upstream matlinuxer2/ucimf).
It is a genuine C++ shared/static library (libucimf.so.0 / libucimf.a).

Build facts (audited from the 2.3.8 tarball, sha256 9fe18e75...d7563):
  * Autotools project (configure pre-generated by upstream autoconf 2.59 era).
    Subdirs: display (framebuffer/VGA graphdev, noinst) -> font (FreeType +
    fontconfig, noinst) -> src (libucimf.la, installed) -> man, sample.
  * Hard configure requirements: AC_CHECK_LIB(ltdl, lt_dlopen) plus
    PKG_CHECK_MODULES(freetype2) and PKG_CHECK_MODULES(fontconfig).
  * The libtool-name of the installed library is libucimf (libucimf.a/.so),
    i.e. consumers link with -lucimf and use the `libucimf` pkg-config module
    (libucimf.pc is installed into libdir/pkgconfig).
  * Platform specifics audited for OHOS (aarch64):
    - src/ucimf.cpp includes <linux/kd.h>, <linux/keyboard.h> and
      <linux/input.h> unconditionally. The OHOS SDK sysroot
      (ohos-sdk_26.0.0.18/native/sysroot/usr/include) ships all three
      headers, so no source patch is required.
    - The x86-only real-mode pieces (display/lrmi.c, display/vgadev.cpp,
      display/fbvgaplanes.cpp) are entirely wrapped in `#ifdef USING_VGA`,
      which nothing defines -> they compile to empty translation units on
      aarch64. No patch needed.
    - display/fbdev.cpp guards <linux/fb.h> with `#if defined(linux)`. The
      OHOS clang driver predefines `linux`/`__linux__` for the
      aarch64-linux-ohos triple, and linux/fb.h exists in the sysroot,
      so FBDev compiles; at runtime TryOpen() simply fails to open
      /dev/fb* and returns FAILURE (graceful, GraphPort handles gdev==0).
  * Upstream ships NO test suite (no check_PROGRAMS/TESTS in any
    Makefile.am; `make check` is a no-op). The sample/ programs
    (console01/console04) call ucimf_init(), which hard-crashes without at
    least one fontconfig-discoverable font (Font::instance() returns NULL
    when FcFontSort finds no fonts -> ->height() NULL deref), so they are
    demo programs, not headless-runnable tests. The test_package therefore
    exercises the deterministic headless consumer workflow instead:
    ucimf_process_raw() on a Ctrl keycode runs the full
    keycode -> keysym -> term-string pipeline (KDGKBENT/KDGKBSENT ioctls
    fail gracefully with ENOTTY on a pipe) and ucimf_switch() passthrough.

OHOS notes:
  * Native build (host = build = OHOS/aarch64) with the worker clang 15,
    per ci/conan/profiles/ohos-aarch64.
  * freetype2/fontconfig are discovered through PkgConfigDeps-generated .pc
    files (PKG_CONFIG_PATH injected by the conanbuild env); libltdl is
    discovered by the AC_CHECK_LIB link probe through the AutotoolsDeps
    LDFLAGS/CppFlags env. Both generators are required: neither alone
    covers both probes.
  * R26: system-name library default is static (--enable-static
    --disable-shared); libtool records the freetype/fontconfig/ltdl
    dependency_libs in libucimf.la so the static archive propagates them
    to consumers through transitive_libs=True requires.
"""
import os

from conan import ConanFile
from conan.tools.env import Environment
from conan.tools.files import get, apply_conandata_patches, export_conandata_patches
from conan.tools.gnu import Autotools, AutotoolsToolchain, AutotoolsDeps, PkgConfigDeps
from conan.tools.layout import basic_layout


class LibucimfConan(ConanFile):
    name = "libucimf"
    version = "2.3.8"
    description = "UCIMF (Unicode Console Input Method Framework) core library"
    license = "GPL-2.0-or-later"
    homepage = "https://github.com/matlinuxer2/ucimf"
    url = "https://github.com/matlinuxer2/ucimf/releases/download/googlecode/libucimf-2.3.8.tar.gz"

    package_type = "library"

    settings = "os", "compiler", "build_type", "arch"
    options = {"shared": [True, False]}
    # freetype/fontconfig: match the shared=True binaries published in the
    # ohpcd registry so the graph reuses prebuilt packages instead of
    # compiling the whole fontconfig stack from source on the worker.
    default_options = {"shared": False, "freetype/*:shared": True, "fontconfig/*:shared": True}

    def export_sources(self):
        export_conandata_patches(self)

    def requirements(self):
        # freetype2 + fontconfig: PKG_CHECK_MODULES probes (font/font.cpp).
        # libltdl: AC_CHECK_LIB(ltdl, lt_dlopen) hard requirement
        # (IMF modules are lt_dlopen'ed at runtime from libdir/ucimf/).
        # transitive_libs: with the R26 static default, libucimf.a pulls
        # freetype/fontconfig/ltdl symbols that consumers must link.
        self.requires("freetype/2.14.3", transitive_headers=True, transitive_libs=True)
        self.requires("fontconfig/2.18.1.1", transitive_headers=True, transitive_libs=True)
        self.requires("libltdl/2.6.0", transitive_libs=True)

    def layout(self):
        basic_layout(self)

    def source(self):
        get(self, **self.conan_data["sources"], strip_root=True)

    def generate(self):
        tc = AutotoolsToolchain(self)
        # R26: system-name libraries default to static.
        if not self.options.shared:
            tc.configure_args.append("--enable-static")
            tc.configure_args.append("--disable-shared")
        tc.generate()
        # .pc files for freetype2/fontconfig (configure PKG_CHECK_MODULES).
        PkgConfigDeps(self).generate()
        # CPPFLAGS/LDFLAGS env for the AC_CHECK_LIB(ltdl) link probe and for
        # linking freetype/fontconfig into the static archive.
        AutotoolsDeps(self).generate()
        # freetype/fontconfig are consumed as shared libraries (ohpcd cache
        # convention); export their libdirs via LD_LIBRARY_PATH so configure's
        # runtime probes ("whether we are cross compiling" runs conftest) and
        # libtool's wrapper relinks can resolve libfreetype.so.6 / libfontconfig
        # / libltdl while building from the build tree.
        env = Environment()
        for _, dep in self.dependencies.items():
            for d in dep.cpp_info.libdirs:
                env.append_path("LD_LIBRARY_PATH", d)
        env.vars(self, scope="build").save_script("conandeps_ldpath")

    def build(self):
        apply_conandata_patches(self)
        autotools = Autotools(self)
        # E551: with CONFIG_SHELL=hnp bash (ohos-aarch64 profile buildenv),
        # the 2011-era ltmain.sh emits a libtool whose archive_expsym_cmds
        # lose their quote escaping ("syntax error near unexpected token `}'"
        # on the $libname.ver~ version-script lines). Regenerate libtool with
        # the /bin/sh dialect: a command-line-prefix assignment wins over the
        # aggregated buildenv CONFIG_SHELL.
        orig_run = self.run

        def _run(cmd, *args_, **kwargs):
            if cmd.lstrip().startswith('"') and "/configure" in cmd:
                cmd = "CONFIG_SHELL=/bin/sh " + cmd
            return orig_run(cmd, *args_, **kwargs)

        self.run = _run
        try:
            autotools.configure()
        finally:
            self.run = orig_run
        autotools.make(args=["-j1"])

    def package(self):
        autotools = Autotools(self)
        autotools.install()

    def package_info(self):
        # Installed as libucimf.a / libucimf.so -> -lucimf.
        self.cpp_info.set_property("cmake_file_name", "libucimf")
        self.cpp_info.set_property("pkg_config_name", "libucimf")
        self.cpp_info.libs = ["ucimf"]
        # libucimf is C++ code; C consumers must link the C++ runtime too
        # (undefined std::__n1 symbols when a C test binary links the
        # static archive without libc++).
        self.cpp_info.system_libs = ["c++"]
        # libdir/ucimf/ is the runtime IMF module dir (IMF_MODULE_DIR);
        # no plugins ship in this package, so nothing to add there.
